<template>
  <section class="preview-shell" aria-label="轮播组件实际字段预览">
    <p class="hint">375 设计宽度预览；链接在编辑器中不执行。已隐藏组件仍显示预览，图片按当前访问权限读取。</p>
    <div class="preview-actions"><button type="button" @click="togglePause">{{paused?'继续轮播预览':'暂停轮播预览'}}</button><span v-if="!p.enabled">发布时隐藏</span><span v-if="p.home && p.stickySearch">搜索随页面滚动吸顶</span></div>
    <div class="carousel-author-preview" :data-kind="p.kind" :data-layout="p.style" :data-index="index" :data-hot-interval="p.hotInterval" :style="p.wrapperStyle">
      <div v-if="p.home && p.items[index]" class="home-background" :style="{backgroundImage:`url(${JSON.stringify(p.items[index]?.image)})`}" />
      <div v-else-if="p.kind==='swiperBg' && p.items.length" class="carousel-background" :style="p.backgroundStyle" />
      <template v-if="p.home">
        <div class="search-header"><div class="search-row"><img v-if="p.logo" class="logo" :src="p.logo" alt="组合搜索 logo" /><div class="search"><span>{{p.hotWords.length?p.hotWords[word % p.hotWords.length]:p.placeholder}}</span><span>⌕</span></div></div></div>
        <div v-if="p.showTabs" class="tabs"><div class="tab-row"><button v-for="tab in p.tabs" :key="tab.index" type="button" :data-tab-index="tab.index" :aria-pressed="selectedTab===tab.index" :class="{invalid:!tab.valid}" :style="{marginRight:`${p.tabGap}px`}" @click="chooseTab(tab.index)">{{tab.label||'未命名'}}</button></div><button type="button" aria-label="预览展开全部轮播分类" @click="toggleCategory">☷</button></div>
        <div v-if="categoryOpen" class="category" :style="{background:p.categoryBackground}"><div class="category-heading">精选类目<button type="button" @click="toggleCategory">关闭分类预览</button></div><div class="category-grid"><button v-for="tab in p.tabs" :key="tab.index" type="button" :aria-pressed="selectedTab===tab.index" @click="chooseTab(tab.index)">{{tab.label||'未命名'}}</button></div></div>
      </template>
      <div v-if="p.items.length" class="preview-canvas" :data-state="imageState">
        <template v-if="p.stacked"><div v-for="item in p.items" :key="`${item.index}:${item.image}`" class="stacked-slide" :style="p.imageStyle"><img :src="item.image" alt="旧版广告图片" :style="p.imageStyle" @load="loaded(item.index,item.image,$event)" @error="failed(item.index,item.image)" /><span v-if="errors[item.index]" role="alert">图片读取失败</span></div></template>
        <div v-else class="slides" :style="{height:`${height}px`}" :data-height="height">
          <div v-for="(item,i) in p.items" :key="`${item.index}:${item.image}`" class="preview-slide" :class="{selected:i===index}" :data-preview-slot="item.index" :style="slideStyle(i)"><img :src="item.image" alt="轮播图片" :style="p.imageStyle" @load="loaded(item.index,item.image,$event)" @error="failed(item.index,item.image)" /><span v-if="errors[item.index]" role="alert">图片读取失败</span></div>
          <span v-if="imageState==='loading'" class="image-status" role="status">图片加载中…</span>
          <span v-if="imageState==='error'" class="image-status" role="alert">轮播图片读取失败</span>
        </div>
        <div v-if="!p.stacked" class="dots" :class="`indicator-${p.indicator}`" :style="{justifyContent:['flex-start','center','flex-end'][p.dotPosition]}">
          <div v-if="p.indicator===2" class="progress" :style="{width:`${p.items.length*10}px`,background:p.dotBackground}"><div :style="{width:`${(index+1)/p.items.length*100}%`,background:p.dotColor}" /></div>
          <button v-for="(_,i) in p.indicator===2?[]:p.items" :key="i" type="button" :aria-label="`预览轮播第 ${i+1} 张`" :aria-pressed="index===i" :style="{background:index===i?p.dotColor:p.dotBackground,...(p.legacy?p.indicator===3?{width:'10px',height:'2.5px',borderRadius:'1.5px'}:{width:'5px',height:'5px',borderRadius:'2.5px'}:{})}" @click="change(i)" />
        </div>
        <div v-if="!p.stacked" class="slide-controls"><button type="button" @click="change((index+p.items.length-1)%p.items.length)">上一张预览</button><span>{{index+1}} / {{p.items.length}}</span><button type="button" @click="change((index+1)%p.items.length)">下一张预览</button></div>
      </div>
      <p v-else class="hint empty">暂无可显示的轮播图片</p>
    </div>
  </section>
</template>
<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from 'vue';
import { carouselPreview, type CarouselRecord } from '@/utils/diyCarouselEditor';
const props=defineProps<{block:CarouselRecord;previews:Record<string,string>;allowed:()=>boolean}>();
const p=computed(()=>carouselPreview(props.block,props.previews)),index=ref(0),word=ref(0),selectedTab=ref(0),categoryOpen=ref(false),height=ref(187.5),errors=ref<Record<number,boolean>>({}),imageState=ref<'loading'|'ready'|'error'>('loading'),paused=ref(false);
let alive=true,slideTimer:ReturnType<typeof setInterval>|null=null,wordTimer:ReturnType<typeof setInterval>|null=null;
const admitted=()=>alive&&props.allowed();
function stop(){if(slideTimer)clearInterval(slideTimer);if(wordTimer)clearInterval(wordTimer);slideTimer=wordTimer=null;}
function timers(){stop();if(paused.value)return;if(p.value.items.length>1&&!p.value.stacked)slideTimer=setInterval(()=>{if(admitted()&&imageState.value==='ready')index.value=(index.value+1)%p.value.items.length;},p.value.interval);if(p.value.home&&p.value.hotWords.length>1)wordTimer=setInterval(()=>{if(admitted())word.value++;},p.value.hotInterval);}
watch(()=>[props.block,props.previews],()=>{index.value=word.value=selectedTab.value=0;categoryOpen.value=false;errors.value={};height.value=p.value.home?160:187.5;imageState.value='loading';timers();},{immediate:true});
onBeforeUnmount(()=>{alive=false;stop();});
function togglePause(){if(!admitted())return;paused.value=!paused.value;timers();}
function change(value:number){if(admitted()&&Number.isInteger(value)&&value>=0&&value<p.value.items.length)index.value=value;}
function chooseTab(value:number){if(admitted()&&p.value.tabs.some(t=>t.index===value)){selectedTab.value=value;categoryOpen.value=false;}}
function toggleCategory(){if(admitted())categoryOpen.value=!categoryOpen.value;}
function loaded(slot:number,source:string,event:Event){if(!admitted()||p.value.items.find(item=>item.index===slot)?.image!==source)return;const img=event.target as HTMLImageElement;if(img.getAttribute('src')!==source||img.currentSrc&&new URL(img.currentSrc,img.baseURI).href!==new URL(source,img.baseURI).href)return;if(!Number.isFinite(img.naturalWidth)||!Number.isFinite(img.naturalHeight)||img.naturalWidth<=0||img.naturalHeight<=0){failed(slot,source);return;}delete errors.value[slot];if(slot!==p.value.items[0]?.index)return;const q=p.value;height.value=q.home?160:q.legacy?(img.naturalHeight+10)/2:img.naturalHeight/img.naturalWidth*Math.max(1,750-q.horizontalPadding*2)/2;imageState.value='ready';}
function failed(slot:number,source:string){if(!admitted()||p.value.items.find(item=>item.index===slot)?.image!==source)return;errors.value[slot]=true;if(slot===p.value.items[0]?.index)imageState.value='error';}
function slideStyle(i:number){const q=p.value,width=Math.max(1,375-(q.legacy?q.horizontalPadding:q.home?0:q.horizontalPadding)-q.previousMargin*2);return{left:`${q.previousMargin+(i-index.value)*width}px`,width:`${width}px`,padding:`0 ${q.gap}px`,transform:`scale(${i===index.value?1:q.inactiveScale})`,borderRadius:q.imageStyle.borderRadius};}
</script>
<style scoped>
