ria-pressed=true]{background:white;color:#333}.preview-canvas{position:relative;width:100%;overflow:hidden}.slides{position:relative;width:100%;overflow:hidden}.preview-slide{position:absolute;top:0;height:100%;box-sizing:border-box;transition:left .5s,transform .3s;overflow:hidden}.preview-slide img{display:block;width:100%;height:100%;object-fit:cover}.preview-slide>span,.stacked-slide>span,.image-status{position:absolute;inset:0;display:grid;place-items:center;background:#f5f5f5;color:#888;font-size:12px}.stacked-slide{position:relative;overflow:hidden}.stacked-slide img{display:block;width:100%;height:auto}.dots{position:absolute;bottom:40px;left:10px;right:10px;display:flex;gap:8px}.dots button{width:6px;height:6px;border:0;border-radius:3px;padding:0;cursor:pointer}.dots.indicator-1{gap:4px}.indicator-1 button{width:5px;height:5px}.indicator-1 button[aria-pressed=true]{width:9px}.dots.indicator-3{gap:5px}.indicator-3 button{width:10px;height:3px;border-radius:1.5px}.progress,.progress>div{height:3px;border-radius:1.5px}.progress>div{transition:width .3s}.slide-controls{position:relative;display:flex;justify-content:space-between;align-items:center;gap:8px;background:white;padding:6px;font-size:11px;color:#666}.empty{padding:12px}
</style>
